import runpy
import unittest


def rodar():
    """Roda solucao.py do zero e devolve o que ele definiu."""
    return runpy.run_path("solucao.py")


class TestListaDeListas(unittest.TestCase):
    def test_nota_de_pega_a_nota_da_linha_e_coluna(self):
        """nota_de devolve a nota na linha e na coluna pedidas"""
        self.assertEqual(rodar()["nota_de"]([[7, 8], [9, 6]], 1, 0), 9)

    def test_nota_de_com_uma_linha_so(self):
        """nota_de com uma linha so usa a coluna dentro dela"""
        self.assertEqual(rodar()["nota_de"]([[5]], 0, 0), 5)

    def test_nota_de_com_outra_celula(self):
        """nota_de devolve a nota de outra celula da tabela"""
        self.assertEqual(rodar()["nota_de"]([[7, 8], [9, 6]], 0, 1), 8)
